css:
.print-format {
 font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}
.header {
 text-align: center;
 border-bottom: 3px solid #2563eb;
 padding-bottom: 15px;
 margin-bottom: 20px;
}
.header h1 {
 color: #2563eb;
 margin: 0;
 font-size: 24px;
}
.section {
 margin: 15px 0;
 padding: 10px 15px;
 background: #f8fafc;
 border-radius: 8px;
 border-left: 4px solid #2563eb;
}
.section h3 {
 color: #1e293b;
 margin: 0 0 10px 0;
 font-size: 16px;
}
.detail-row {
 display: flex;
 justify-content: space-between;
 padding: 4px 0;
 border-bottom: 1px solid #e2e8f0;
}
.label { color: #64748b; font-weight: 500; }
.value { color: #1e293b; font-weight: 600; }
.score { 
 background: #2563eb;
 color: white;
 padding: 2px 8px;
 border-radius: 12px;
 font-size: 14px;
}
